  const entry = handler as EventHandler<TaskflowEventType>;
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(entry);
  handlers.set(type, set);
  return () => {
    const live = handlers.get(type);
    if (!live || !live.has(entry)) return;
    const next: HandlerSet = new Set(live);
    next.delete(entry);
    handlers.set(type, next);
  };
}

